        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `ShutdownTServer` class allowing multiple shutdown requests to be sent to the master for the same tablet server. This could lead to unnecessary operations and potential inconsistencies in the server's state, as the system may attempt to shut down a server that is already in the process of shutting down.

        Commit message:
        ACCUMULO-3897 Only request shutdown to master once for
 tserver  

        Patch:

   @Override
   public long isReady(long tid, Master master) throws Exception {
     // suppress assignment of tablets to the server
     if (force) {
       return 0;
     }

     // Inform the master that we want this server to shutdown
     // We don't want to spam the master with shutdown requests, so
     // only send this request once
     if (!requestedShutdown) {
       master.shutdownTServer(server);
+      requestedShutdown = true;
     }

     if (master.onlineTabletServers().contains(server)) {
       TServerConnection connection = master.getConnection(server);
       if (connection != null) {
         try {
           TabletServerStatus status = connection.getTableMap(false);
           if (status.tableMap != null && status.tableMap.isEmpty()) {
             log.info("tablet server hosts no tablets " + server);
             connection.halt(master.getMasterLock());
             log.info("tablet server asked to halt " + server);
             return 0;
           }
         } catch (TTransportException ex) {
           // expected
         } catch (Exception ex) {
           log.error("Error talking to tablet server " + server + ": " + ex);
         }

         // If the connection was non-null and we could communicate with it
         // give the master some more time to tell it to stop and for the
         // tserver to ack the request and stop itself.
         return 1000;
       }
     }

     return 0;
   }



